// OTOMATİK ÜRETİLİR (_tasarim/araclar/p345-gom.py) — elle düzenleme. GPT Paket 5 nesne grafikleri (örs, pusula, defter, mektup, makara, fener, flamalar, Kader Çarkı parçaları).
// 11 görsel, WebP base64 (96 KB); ilk kullanımda Blob URL'ye çevrilir.
const D = {
"ors":"",
"pusula":"",
"defter":"",
"mektup":"",
"makara":"",
"fener":"",
"flama-ocak":"",
"flama-sancak":"",
"parca-kor":"",
"parca-ayaz":"",
"parca-simsek":"",
};
const U = {};
// Anahtarın Blob URL'si; yoksa null
export const url = k => { if (U[k]) return U[k]; const s = D[k]; if (!s) return null;
  try { const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return (U[k] = URL.createObjectURL(new Blob([a], { type: 'image/webp' }))); }
  catch { return (U[k] = 'data:image/webp;base64,' + s); } };
export const KEYS = Object.keys(D);

